args<-commandArgs(trailingOnly=FALSE);root<-normalizePath(file.path(dirname(sub("^--file=","",args[grepl("^--file=",args)])),".."),winslash="/");source(file.path(root,"lib","interpro_pfam_analysis.R"))
catalog<-data.frame(source_row=c(1,2,3,4,5),original_id=c("a","a2","iso","group","none"),uniprot_accession=c("P1","P1","P1-2","P2;P3",NA));coverage<-data.frame(requested_accession=c("P1","P1-2"),annotation_status=c("annotated","no_matches"));m<-protein_mapping(catalog,coverage)
stopifnot(sum(m$mapping_status=="mapped_unique")==3);stopifnot(length(unique_proteins(m))==2);stopifnot("P1-2"%in%unique_proteins(m));stopifnot(any(m$mapping_status=="ambiguous"));stopifnot(any(m$mapping_status=="unmapped"));stopifnot(any(m$annotation_status=="no_matches",na.rm=TRUE));stopifnot(grepl("1;2",m$source_rows[m$uniprot_accession=="P1"][[1]]))
membership<-data.frame(uniprot_accession=c("P1","P1","P1-2"),feature=c("F1","F1","F2"),name=c("one","one","two"),type=c("domain","domain","family"));freq<-feature_frequency(membership,c("P1","P1-2"),"feature","name","type");stopifnot(freq$Protein_count[freq$feature=="F1"]==1);stopifnot(freq$Target_size[[1]]==2);stopifnot(all(c("domain","family")%in%freq$type))
enr<-feature_enrichment(membership,"P1",c("P1","P1-2"),"feature","name","type",1);stopifnot(nrow(enr$tested)==1);stopifnot(enr$tested$Reference_size[[1]]==1);stopifnot(!is.na(enr$tested$p_value[[1]]));stopifnot(!is.na(enr$tested$FDR[[1]]));excluded<-feature_enrichment(membership,"P1",c("P1","P1-2"),"feature","name","type",2);stopifnot(nrow(excluded$tested)==0);stopifnot(nrow(excluded$excluded)==2)
adjust<-adjust_protein_sets(c("P1","P2"),"P1",FALSE);stopifnot(!adjust$ok);stopifnot(identical(adjust$outside,"P2"));stopifnot(adjust_protein_sets(c("P1","P2"),"P1",TRUE)$ok);stopifnot(identical(adjust_protein_sets(c("P1","P2"),"P1",TRUE)$target,"P1"))
locations<-data.frame(uniprot_accession=c("P1","P1","P1","P1"),feature=c("F1","F2","F1","SITE"),start=c(10,40,100,20),end=c(50,80,140,21),location_index=1:4,fragment_index=1,entry_type=c("domain","repeat","domain","site"));rep<-repeated_features(locations,"Pfam","feature");stopifnot(nrow(rep)==1);stopifnot(rep$Occurrence_count[[1]]==2);arch<-architecture_table(c("P1","EMPTY"),locations,"feature");stopifnot(arch$Architecture[[1]]=="F1 > SITE > F2 > F1");stopifnot(arch$Has_repeated_feature[[1]]);stopifnot(arch$Has_overlap[[1]]);stopifnot(is.na(arch$Architecture[[2]]));structural<-architecture_table("P1",locations,"feature",c("domain","repeat"));stopifnot(structural$Architecture[[1]]=="F1 > F2 > F1");stopifnot(!grepl("SITE",structural$Architecture[[1]]));af<-architecture_frequency(structural,"P1");stopifnot(nrow(af)==1);stopifnot(af$Protein_count[[1]]==1);ls<-location_summary(c("P1","EMPTY"),locations,locations);stopifnot(ls$number_of_Pfam_locations[[1]]==4);stopifnot(ls$number_of_Pfam_locations[[2]]==0)
empty<-feature_frequency(membership[0,],"P1","feature","name","type");stopifnot(nrow(empty)==0);zero<-feature_enrichment(membership[0,],"P1",c("P1","P2"),"feature","name","type",1);stopifnot(nrow(zero$tested)==0);stopifnot(nrow(zero$excluded)==0)
cat("R InterPro/Pfam tests passed: 35 checks\n")
